      ? c.body(null, 204)
      : c.json({ error: { code: "not_found", message: "Task not found" } }, 404),
  );

  app.get("/",serveStatic''')
open(p,'w').write(s)
p='public/app.js'
s=open(p).read()
s=s.replace('''      item.textContent = task.title;
''','''      item.textContent = task.title;
